  "inlineSchema": "// Prisma schema file for VoteChain\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ------------------------------------------------------\n// Enums\n// ------------------------------------------------------\n\nenum Role {\n  REGISTRAR\n  VOTER\n  ADMIN\n  AUDITOR\n}\n\nenum OTPPurpose {\n  LOGIN\n  REGISTRATION\n}\n\nenum ElectionStatus {\n  DRAFT\n  PUBLISHED\n  CLOSED\n  RESULTS_PUBLISHED\n}\n\nenum TransactionStatus {\n  PENDING\n  CONFIRMED\n  FAILED\n}\n\nenum AuditEventType {\n  AUTH_LOGIN\n  OTP_SENT\n  OTP_VERIFIED\n  VOTER_REGISTERED\n  CREDENTIAL_ISSUED\n  BALLOT_CREATED\n  BALLOT_HASHED\n  BLOCKCHAIN_SUBMITTED\n  BLOCKCHAIN_CONFIRMED\n  CREDENTIAL_USED\n  VERIFICATION_PERFORMED\n  ELECTION_CREATED\n  ELECTION_PUBLISHED\n  ELECTION_CLOSED\n  RESULTS_PUBLISHED\n}\n\n// ------------------------------------------------------\n// Models\n// ------------------------------------------------------\n\nmodel MockAadhaar {\n  id            String   @id @default(uuid())\n  aadhaarNumber String   @unique\n  fullName      String\n  dateOfBirth   DateTime\n  gender        String\n  address       String\n  phone         String\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  voterProfile VoterProfile?\n}\n\nmodel User {\n  id           String   @id @default(uuid())\n  email        String   @unique\n  passwordHash String\n  role         Role\n  isActive     Boolean  @default(true)\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  voterProfile       VoterProfile?\n  registeredProfiles VoterProfile[] @relation(\"RegistrarVoterProfiles\")\n  createdElections   Election[]     @relation(\"AdminElections\")\n  otpCodes           OTPCode[]\n  auditRecords       AuditRecord[]  @relation(\"ActorUserAuditRecords\")\n}\n\nmodel VoterProfile {\n  id                 String      @id @default(uuid())\n  userId             String      @unique\n  user               User        @relation(fields: [userId], references: [id], onDelete: Cascade)\n  aadhaarId          String      @unique\n  aadhaar            MockAadhaar @relation(fields: [aadhaarId], references: [id], onDelete: Cascade)\n  registeredByUserId String\n  registeredByUser   User        @relation(\"RegistrarVoterProfiles\", fields: [registeredByUserId], references: [id])\n  createdAt          DateTime    @default(now())\n  updatedAt          DateTime    @updatedAt\n\n  eligibilities VoterEligibility[]\n}\n\nmodel VoterEligibility {\n  id             String       @id @default(uuid())\n  voterProfileId String\n  voterProfile   VoterProfile @relation(fields: [voterProfileId], references: [id], onDelete: Cascade)\n  electionId     String\n  election       Election     @relation(fields: [electionId], references: [id], onDelete: Cascade)\n  isEligible     Boolean\n  reason         String?\n  createdAt      DateTime     @default(now())\n  updatedAt      DateTime     @updatedAt\n\n  credential AnonymousCredential?\n\n  @@unique([voterProfileId, electionId])\n}\n\nmodel OTPCode {\n  id         String     @id @default(uuid())\n  userId     String\n  user       User       @relation(fields: [userId], references: [id], onDelete: Cascade)\n  codeHash   String\n  purpose    OTPPurpose\n  expiresAt  DateTime\n  consumedAt DateTime?\n  createdAt  DateTime   @default(now())\n}\n\nmodel Election {\n  id              String         @id @default(uuid())\n  title           String\n  description     String\n  status          ElectionStatus @default(DRAFT)\n  startDate       DateTime\n  endDate         DateTime\n  createdByUserId String\n  createdByUser   User           @relation(\"AdminElections\", fields: [createdByUserId], references: [id])\n  createdAt       DateTime       @default(now())\n  updatedAt       DateTime       @updatedAt\n\n  candidates    Candidate[]\n  eligibilities VoterEligibility[]\n  credentials   AnonymousCredential[]\n  ballots       Ballot[]\n  transactions  BlockchainTransaction[]\n  auditRecords  AuditRecord[]\n}\n\nmodel Candidate {\n  id         String   @id @default(uuid())\n  electionId String\n  election   Election @relation(fields: [electionId], references: [id], onDelete: Cascade)\n  name       String\n  party      String\n  symbolUrl  String?\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  ballots Ballot[]\n}\n\nmodel AnonymousCredential {\n  id                 String           @id @default(uuid())\n  credentialHash     String           @unique\n  electionId         String\n  election           Election         @relation(fields: [electionId], references: [id], onDelete: Cascade)\n  voterEligibilityId String           @unique\n  voterEligibility   VoterEligibility @relation(fields: [voterEligibilityId], references: [id], onDelete: Cascade)\n  isUsed             Boolean          @default(false)\n  issuedAt           DateTime         @default(now())\n  usedAt             DateTime?\n}\n\nmodel Ballot {\n  id               String                 @id @default(uuid())\n  electionId       String\n  election         Election               @relation(fields: [electionId], references: [id], onDelete: Cascade)\n  candidateId      String\n  candidate        Candidate              @relation(fields: [candidateId], references: [id])\n  credentialHash   String\n  encryptedPayload String\n  ballotHash       String                 @unique\n  transactionId    String?                @unique\n  transaction      BlockchainTransaction? @relation(fields: [transactionId], references: [id])\n  createdAt        DateTime               @default(now())\n}\n\nmodel BlockchainTransaction {\n  id          String            @id @default(uuid())\n  txId        String            @unique\n  electionId  String\n  election    Election          @relation(fields: [electionId], references: [id], onDelete: Cascade)\n  ballotHash  String\n  blockNumber Int?\n  status      TransactionStatus @default(PENDING)\n  confirmedAt DateTime?\n  createdAt   DateTime          @default(now())\n\n  ballot Ballot?\n}\n\nmodel AuditRecord {\n  id          String         @id @default(uuid())\n  eventType   AuditEventType\n  electionId  String?\n  election    Election?      @relation(fields: [electionId], references: [id], onDelete: SetNull)\n  actorUserId String?\n  actorUser   User?          @relation(\"ActorUserAuditRecords\", fields: [actorUserId], references: [id], onDelete: SetNull)\n  metadata    Json?\n  timestamp   DateTime       @default(now())\n}\n",
